data.script:
function check(value,message){if(!value)throw new Error(message);}
const modes=ModelSession.availableModes();
check(Array.isArray(modes),'mode array');
const lines=['Apple model availability — neutral QA','modes='+JSON.stringify(modes)];
for(const mode of ['onDevice','pcc']){
 const session=ModelSession.create(mode);session.toolSets=[];
 check(session.isAvailable===modes.includes(mode),'instance availability '+mode);
 check(ModelSession.isAvailable(mode)===modes.includes(mode),'static availability '+mode);
 if(session.isAvailable){lines.push(mode+': available; generation not requested');continue;}
 const result=session.respond('Return neutral.');
 check(result===undefined,'unavailable result '+mode);
 check(typeof session.lastError==='string' && session.lastError.includes('unavailable'),'explicit unavailable error '+mode);
 lines.push(mode+': unavailable; '+session.lastError);
}
editor.setText(lines.join('\n'));draft.update();
